 if(m==='PUT'&&route(p,/^\/api\/jobs\/([^/]+)$/)){const j=owner(db.jobs.find(x=>x.id===p.split('/')[3]),u),b=await input(req);for(const k of ['title','description','neighborhood','contract','salary','schedule','mode','requirements'])if(b[k]!==undefined)j[k]=str(b[k],k==='description'?1200:k==='requirements'?600:100);if(['open','draft','paused','closed'].includes(b.status))j.status=b.status;j.updatedAt=now();await save();return json(res,200,{job:jobView(j,u)})}
