async function socialApi(req,res,url,u){
 const p=url.pathname,m=req.method;
 if(p.startsWith('/api/admin/')){requireUser(u);if(!process.env.ADMIN_EMAIL||u.email!==process.env.ADMIN_EMAIL.toLowerCase())err(403,'Acesso restrito.');if(m==='GET'&&p==='/api/admin/reports')return json(res,200,{reports:db.reports.slice().reverse()});if(m==='POST'&&route(p,/^\/api\/admin\/reports\/([^/]+)\/resolve$/)){const r=db.reports.find(x=>x.id===p.split('/')[4]);if(!r)err(404,'Denúncia não encontrada.');const b=await input(req);r.status='resolved';r.resolution=str(b.resolution,600)||'Analisado';r.resolvedAt=now();r.resolvedBy=u.id;if(b.pause&&r.targetType==='service'){const l=db.listings.find(x=>x.id===r.targetId);if(l)l.status='paused'}if(b.pause&&r.targetType==='product'){const x=db.products.find(v=>v.id===r.targetId);if(x)x.status='paused'}if(b.pause&&r.targetType==='job'){const j=db.jobs.find(x=>x.id===r.targetId);if(j)j.status='paused'}notice(r.userId,'report','Sua denúncia foi analisada','/minha-area');await save();return json(res,200,{report:r})}}
 if(m==='GET'&&p==='/api/chats'){requireUser(u);return json(res,200,{chats:db.conversations.filter(x=>x.userIds.includes(u.id)).map(x=>({...x,other:cp(db.users.find(v=>v.id===x.userIds.find(z=>z!==u.id))),lastMessage:x.messages.at(-1)||null,messageCount:x.messages.length,messages:undefined})).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))})}
 if(m==='POST'&&p==='/api/chats'){requireUser(u);const b=await input(req),target=db.users.find(x=>x.id===b.targetId);if(!target||target.id===u.id||target.blocked?.includes(u.id)||u.blocked?.includes(target.id))err(400,'Contato indisponível.');let type='general',contextId='';if(b.listingId){const l=db.listings.find(x=>x.id===b.listingId&&x.userId===target.id);if(!l)err(400,'Serviço inválido.');type='service';contextId=l.id}else if(b.productId){const x=db.products.find(v=>v.id===b.productId&&v.userId===target.id);if(!x)err(400,'Produto inválido.');type='product';contextId=x.id}else if(b.jobId){const j=db.jobs.find(x=>x.id===b.jobId&&(x.userId===target.id||x.userId===u.id));if(!j)err(400,'Vaga inválida.');type='job';contextId=j.id}const c=conversation(u.id,target.id,type,contextId);await save();return json(res,200,{chatId:c.id})}
 if(route(p,/^\/api\/chats\/([^/]+)$/)){requireUser(u);const c=db.conversations.find(x=>x.id===p.split('/')[3]&&x.userIds.includes(u.id));if(!c)err(404,'Conversa não encontrada.');if(m==='GET')return json(res,200,{chat:{...c,other:cp(db.users.find(x=>x.id===c.userIds.find(y=>y!==u.id)))}});if(m==='POST'){const b=await input(req),text=str(b.text,2000);if(!text)err(400,'Escreva uma mensagem.');const targetId=c.userIds.find(x=>x!==u.id),target=db.users.find(x=>x.id===targetId);if(target?.blocked?.includes(u.id)||u.blocked?.includes(targetId))err(403,'Esta conversa está bloqueada.');const msg={id:id(),userId:u.id,text,createdAt:now()};c.messages.push(msg);c.updatedAt=msg.createdAt;notice(targetId,'message','Nova mensagem de '+u.name,'/mensagens/'+c.id);await save();return json(res,201,{message:msg})}}
 if(m==='POST'&&p==='/api/invites'){need(u,'business');const b=await input(req),j=db.jobs.find(x=>x.id===b.jobId&&x.userId===u.id&&x.status==='open'),target=db.users.find(x=>x.id===b.targetId&&has(x,'candidate')&&x.profile?.talentVisible);if(!j||!target||target.blocked?.includes(u.id))err(400,'Vaga ou talento indisponível.');if(db.invites.some(x=>x.jobId===j.id&&x.targetId===target.id&&x.status==='pending'))err(409,'Convite já enviado.');const inv={id:id(),jobId:j.id,targetId:target.id,userId:u.id,message:str(b.message,400),status:'pending',createdAt:now()};db.invites.push(inv);notice(target.id,'invite','Convite para vaga: '+j.title,'/convites/'+inv.id);await save();return json(res,201,{invite:inv})}
 if(m==='GET'&&p==='/api/invites'){requireUser(u);return json(res,200,{invites:db.invites.filter(x=>x.targetId===u.id||x.userId===u.id).map(x=>({...x,job:jobView(db.jobs.find(j=>j.id===x.jobId)||{},u),sender:cp(db.users.find(v=>v.id===x.userId))})).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))})}
 if(m==='POST'&&route(p,/^\/api\/invites\/([^/]+)\/respond$/)){requireUser(u);const inv=db.invites.find(x=>x.id===p.split('/')[3]&&x.targetId===u.id);if(!inv||inv.status!=='pending')err(404,'Convite indisponível.');const b=await input(req);inv.status=b.accept?'accepted':'declined';inv.updatedAt=now();notice(inv.userId,'invite',u.name+(b.accept?' aceitou':' recusou')+' o convite','/minhas-vagas');await save();return json(res,200,{invite:inv})}
 if(m==='POST'&&p==='/api/reports'){requireUser(u);const b=await input(req),type=str(b.targetType,30),targetId=str(b.targetId,80),reason=str(b.reason,700);if(!['service','product','profile','job','chat','order','product_order','application'].includes(type)||!targetId||reason.length<5)err(400,'Informe o motivo da denúncia.');const r={id:id(),userId:u.id,targetType:type,targetId,reason,status:'open',createdAt:now()};db.reports.push(r);await save();return json(res,201,{report:r})}
 if(m==='POST'&&p==='/api/block'){requireUser(u);const b=await input(req),targetId=str(b.targetId,80);if(!db.users.some(x=>x.id===targetId)||targetId===u.id)err(400,'Perfil inválido.');u.blocked ||= [];if(b.block&&!u.blocked.includes(targetId))u.blocked.push(targetId);if(!b.block)u.blocked=u.blocked.filter(x=>x!==targetId);await save();return json(res,200,{blocked:u.blocked})}
 return false;
}

const mime={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.webp':'image/webp','.svg':'image/svg+xml','.ico':'image/x-icon'};
async function staticFile(req,res,p){
 let file=path.resolve(publicDir,'.'+p);if(file!==publicDir&&!file.startsWith(publicDir+path.sep))return json(res,404,{error:'Página não encontrada.'});
 if(p==='/'||!path.extname(p))file=path.join(publicDir,'index.html');
 try{const data=await readFile(file);res.writeHead(200,{'Content-Type':mime[path.extname(file)]||'application/octet-stream','X-Content-Type-Options':'nosniff','Cache-Control':file.endsWith('index.html')?'no-store':'public, max-age=3600'});res.end(data)}catch{json(res,404,{error:'Página não encontrada.'})}
}
const server=http.createServer(async(req,res)=>{
 res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('X-Frame-Options','DENY');res.setHeader('Referrer-Policy','strict-origin-when-cross-origin');
 const url=new URL(req.url,'http://'+(req.headers.host||'localhost')),p=url.pathname;
 try{
  if(req.method==='GET'&&p.startsWith('/media/'))return serveMedia(req,res,p.split('/')[2]);
  if(!p.startsWith('/api/'))return staticFile(req,res,p);
  if(['POST','PUT','DELETE'].includes(req.method)&&req.headers.origin){if(new URL(req.headers.origin).host!==req.headers.host)err(403,'Origem não permitida.')}
  const u=me(req);
  for(const handler of [api,productOrdersApi,ordersApi,jobsApi,socialApi]){const result=await handler(req,res,url,u);if(result!==false)return}
  json(res,404,{error:'Recurso não encontrado.'});
 }catch(e){console.error(e.status?e.message:e);json(res,e.status||500,{error:e.status?e.message:'Ocorreu um erro. Tente novamente.'})}
});
const port=Number(process.env.PORT)||3000,host=process.env.HOST||'127.0.0.1';
server.listen(port,host,()=>console.log('Emprega+ em http://'+host+':'+port));
if(process.env.EMAIL_WEBHOOK_URL?.startsWith('https://')){
 let sending=false;
 setInterval(async()=>{
  if(sending)return;sending=true;
  try{for(const n of db.notifications.filter(x=>x.emailStatus==='pending'&&(!x.nextEmailAttempt||x.nextEmailAttempt<Date.now())).slice(0,10)){const to=db.users.find(x=>x.id===n.userId)?.email;if(!to){n.emailStatus='skipped';continue}try{const r=await fetch(process.env.EMAIL_WEBHOOK_URL,{method:'POST',headers:{'Content-Type':'application/json',...(process.env.EMAIL_WEBHOOK_TOKEN?{Authorization:'Bearer '+process.env.EMAIL_WEBHOOK_TOKEN}:{})},body:JSON.stringify({to,subject:n.title,text:n.title+'\n\nAcesse o Emprega+ para responder.',path:n.href})});if(!r.ok)throw new Error('Falha de entrega');n.emailStatus='sent'}catch{n.nextEmailAttempt=Date.now()+15*60000}await save()}}finally{sending=false}
 },30000).unref();
}
